def count_substrings(s):
    """Count the number of substrings with the sum of digits equal to their length.

    Args:
        s: A string containing digits (0-9).

    Returns:
        An integer representing the number of substrings with the sum of digits equal to their length.
    """
    if not s:
        return 0

    total = 0
    for ch in s:
        total += int(ch)

    return total - len(s)

def is_Monotonic(arr):
    """Check if the given array is monotonic.

    Args:
        arr: A list of integers.

    Returns:
        True if the array is monotonic, False otherwise.
    """
    if len(arr) < 2:
        return False
    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            return False
    return True

