def divisor(n):
    """Return the number of divisors of n."""
    if n <= 1:
        return 0
    divisors = 1
    for i in range(2, n):
        if n % i == 0:
            divisors += 1
    return divisors

def frequency_lists(lst):
    """Return a dictionary mapping each element in a flattened list to its frequency.

    Args:
        lst: A list of lists, where each inner list is a list of elements.

    Returns:
        A dictionary where keys are elements from the input list, and values
        are the frequencies of each element.
    """
    freq = {}
    for lst in lst:
        for element in lst:
            freq[element] = freq.get(element, 0) + 1
    return freq

