def combinations_colors(nums, n):
    """Generate all combinations of the given list of integers and return a list of tuples.

    Args:
        nums: A list of integers.
        n: The length of the list.

    Returns:
        A list of tuples, each tuple is a combination of the elements of nums
        and the length of the combination.
    """
    if n == 0:
        return []
    if len(nums) != n:
        raise ValueError("Input list must be of length n")
    if n == 1:
        return [(nums[0], 1)]
    if n == 2:
        return [(nums[0], nums[1])]

    result = []
    for i in range(1, n):
        for j in range(i):
            result.append((nums[i], nums[j]))
    return result

def newman_prime(n: int) -> int:
    """Return the nth newman–shanks–williams prime number.

    Args:
        n: A positive integer.

    Returns:
        The nth prime number.

    Raises:
        ValueError: If n is not a positive integer.
    """
    if not isinstance(n, int) or n <= 0:
        raise ValueError("n must be a positive integer")
    if n == 1:
        return 1
    if n == 2:
        return 2
    if n % 2 == 0:
        return 2
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return i
    return n

