def heap_queue_largest(numbers):
    """Return the n largest numbers from the input list in descending order.

    Args:
        numbers: A list of integers.

    Returns:
        A list of the n largest integers in descending order.
    """
    heap = []
    for num in numbers:
        if heap and heap[0] > num:
            heap[0] = num
        if heap and heap[1] > num:
            heap[1] = num
        if heap and heap[0] > num:
            heap[0] = num
        if heap and heap[1] > num:
            heap[1] = num
    return [num for num in heap if num > 0]

