import math

def surfacearea_sphere(radius):
    """Return the surface area of a sphere given its radius."""
    return math.pi * radius ** 2

def isclose(surfacearea, tol=0.001):
    """Check if a surface area is within a tolerance."""
    return math.isclose(surfacearea, tol, rel_tol=1e-6)

def longest_word(s: str) -> int:
    """Return the length of the longest word in the given string.

    Args:
        s: A string (may be empty).

    Returns:
        The length of the longest word in the string.
    """
    if not s:
        return 0
    max_len = 0
    for i in range(len(s)):
        if s[i] == ' ':
            continue
        else:
            max_len = max(max_len, len(s[i]))
    return max_len

def Find_Min_Length(matrix):
    """Return the length of the smallest list in the given matrix.

    Args:
        matrix: A list of lists of integers.

    Returns:
        An integer representing the length of the smallest list.
    """
    if not matrix:
        return 0
    min_len = float('inf')
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            if matrix[i][j] < min_len:
                min_len = matrix[i][j]
    return min_len

def divisor(n: int) -> int:
    """Return the number of divisors of a given integer n.

    Args:
        n: A positive integer.

    Returns:
        The number of divisors of n.

    Raises:
        ValueError: If n is not a positive integer.
    """
    if not isinstance(n, int) or n <= 0:
        raise ValueError("n must be a positive integer")
    if n == 1:
        return 1
    if n % 2 == 0:
        return 2
    return 3 + divisor(n // 2)

def next_smallest_palindrome(n: int) -> int:
    """Return the next smallest palindrome of the given integer.

    Args:
        n: A non-negative integer.

    Returns:
        The next smallest palindrome that is a palindrome of the given integer.
        If n is 0, returns 0.

    Raises:
        ValueError: If n is negative.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    if n == 0:
        return 0
    if n == 1:
        return 1
    # Check for odd-length palindromes
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return i
    # Check for even-length palindromes
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return i
    raise ValueError("Input must be a non-negative integer.")

def eulerian_num(n: int, m: int) -> int:
    """Return the Eulerian number a(n, m) = n! / (n - 1)!."""
    return n * (n - 1) // 2

