def odd_Equivalent(s: str, n: int) -> int:
    """Return the number of numbers with an odd value when rotating a binary string.

    Args:
        s: A string of characters '0' and '1'.
        n: The number of times to rotate the string.

    Returns:
        The number of times the string is rotated to the right by n positions.
    """
    if n == 0:
        return 0
    if n % 2 == 0:
        return n - 1
    return n - 1 - odd_Equivalent(s, n // 2)

