def max_occurrences(nums):
    """Return the maximum number of times any element appears in the list.

    Args:
        nums: A list of integers.

    Returns:
        The maximum count of any element in the list.
    """
    max_count = 0
    for num in nums:
        if num == 0:
            continue
        count = 0
        for i in range(len(nums)):
            if nums[i] == num:
                count += 1
        if count > max_count:
            max_count = count
    return max_count

def is_Sum_Of_Powers_Of_Two(n: int) -> bool:
    """
    Determine if a given integer is a sum of non-zero powers of 2 or not.

    Args:
        n: A non-negative integer.

    Returns:
        True if n is a sum of non-zero powers of 2 or not, False otherwise.
    """
    if n == 0:
        return False
    if n == 1:
        return True
    if n % 2 == 0:
        return False
    return is_Sum_Of_Powers_Of_Two(n // 2)

