def find_Rotations(s):
    """Return the minimum number of rotations needed to get the same string.

    Args:
        s: A string.

    Returns:
        int: The minimum number of rotations needed.
    """
    if len(s) == 0:
        return 0
    if len(s) == 1:
        return 1

    # dp[i] = min rotations to get s[i]
    dp = [0] * (len(s) + 1)
    dp[0] = 0

    for i in range(1, len(s)):
        for j in range(i):
            if s[i - j] == s[i - j + 1]:
                dp[i] = min(dp[i], dp[i - j] + 1)

    return dp[len(s) - 1]

def remove_dirty_chars(s: str, chars: str) -> str:
    """Remove characters from the first string that are present in the second string.

    Args:
        s: The input string.
        chars: The string to remove characters from.

    Returns:
        A new string with characters removed from the first string.
    """
    result = []
    for char in chars:
        if char in s:
            result.append(char)
    return ''.join(result)

