def Find_Min_Length(List):
    """Return the length of the smallest list in a list of lists.

    Args:
        List: A list of lists, where each inner list is a list of integers.

    Returns:
        The length of the smallest list in the list.
    """
    if not List:
        return 0
    min_len = min(len(List), key=len)
    for i in range(min_len):
        if List[i] < List[i + 1]:
            return i + 1
    return len(List)

