def eulerian_num(n, m):
    """Return the Eulerian number a(n, m) modulo 1e9 + 7.

    Args:
        n (int): The number of digits.
        m (int): The modulus.

    Returns:
        int: The Eulerian number.
    """
    if n == 0 or m == 0:
        return 0
    if n == 1:
        return 1
    if m == 1:
        return 2
    if n % 2 == 0:
        return eulerian_num(n // 2, m) + 1
    else:
        return eulerian_num(n // 2, m) + 2

def find_length(binary_string: str) -> int:
    """Return the length of the longest substring without repeating characters.

    Args:
        binary_string: A string consisting of '0' and '1' characters.

    Returns:
        The length of the longest substring without repeating characters.
    """
    if not binary_string:
        return 0

    max_length = 0
    current_length = 0

    for char in binary_string:
        if char == '1':
            current_length += 1
        else:
            current_length = 0

        if current_length > max_length:
            max_length = current_length

    return max_length

