def count_odd_pairs(x):
    """Return the number of pairs (i, j) with i < j such that x ^ i ^ j is odd.

    Args:
        x: An integer.

    Returns:
        An integer count of pairs (i, j) where i < j such that x ^ i ^ j is odd.
    """
    count = 0
    for i in range(1, x):
        for j in range(i + 1, x):
            if x ^ i ^ j is odd:
                count += 1
    return count

