def unique_sublists(lists):
    """Return a dictionary mapping each list to its occurencies.

    Args:
        lists: A list of lists, each containing integers or floats.

    Returns:
        A dictionary where each key is a list of integers and the value is
        the number of occurencies in the corresponding list.
    """
    occurencies = {}
    for list in lists:
        for item in list:
            occurencies[item] = occurencies.get(item, 0) + 1
    return occurencies

