def is_perfect_square(n: int) -> bool:
    """Return True if n is a perfect square, False otherwise.

    Args:
        n: An integer.

    Returns:
        True if n is a perfect square, False otherwise.
    """
    if n < 0:
        return False
    if n == 0 or n == 1:
        return True
    if n % 2 == 0:
        return False
    return is_perfect_square(n // 2)

def max_run_uppercase(s: str) -> int:
    """Return the maximum run of uppercase characters in the string.

    Args:
        s: A string (can be empty).

    Returns:
        The maximum run length.
    """
    if not s:
        return 0
    max_run = 0
    for char in s:
        if char.isupper():
            max_run = max(max_run, 1 + max_run_uppercase(char))
        else:
            max_run = max(max_run, 1 + max_run_uppercase(char))
    return max_run
